// Interactive local examples only. No provider, message, signup, or connection API calls.
window.WhatsAppPreview = (() => {
  let state='ready', outcome='success', selected=null;
  const initial=()=>[{id:1,phone:'966500000001',status:'active',primary:true},{id:2,phone:'966500000002',status:'inactive'},{id:3,phone:'',status:'pending'},{id:4,phone:'966500000004',status:'expired'}];
  let numbers=initial(), requests=[{id:1,source:'legacy',status:'completed',phone:'966500000001'},{id:2,source:'current',status:'rejected',phone:'966500000003'}];
  const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const btn=(label,action,id='',extra='')=>`<button type="button" class="button" data-wa-action="${action}" data-wa-id="${e(id)}" ${extra}>${label}</button>`;
  const labels={active:'مفعّل',inactive:'متوقف',pending:'بانتظار الربط',expired:'منتهي',completed:'اكتمل الربط سابقًا',rejected:'لم تتم الموافقة',approved:'جاهز للمسح'};
  const hints={pause:'يتوقف استخدامه داخل ساري. تبقى جلسة المزود وسجلاتك محفوظة؛ يصبح رقم مفعّل آخر أساسيًا إن وجد.',activate:'يُتحقق من المزود والباقة قبل التفعيل.',primary:'يستخدم ساري هذا الرقم في العمليات التي تعتمد الرقم الأساسي بعد نجاح الحفظ.',change:'تُنهى جلسة هذا الرقم لدى Green API وتتوقف خدمته. امسح رمزًا جديدًا ثم فعّل الرقم في ساري. تبقى الأرقام الأخرى وسجل الطلبات.'};
  const titles={pause:'إيقاف هذا الرقم في ساري؟',activate:'تفعيل هذا الرقم؟',primary:'استخدام هذا الرقم كأساسي؟',change:'تسجيل خروج هذا الرقم لتغييره؟'};
  function renderPage(){
    const open=requests.some(r=>['pending','approved'].includes(r.status));
    return `<div class="wa-workspace"><div class="wa-controls"><label for="wa-state">حالة الصفحة في المثال<select id="wa-state">${[['ready','بيانات متنوعة'],['empty','فارغ'],['pending','طلب سابق قيد المراجعة'],['approved','طلب جاهز للمسح'],['error','تعذّر التحميل'],['loading','جارٍ التحميل']].map(([v,label])=>`<option value="${v}" ${state===v?'selected':''}>${label}</option>`).join('')}</select></label><label for="wa-outcome">نتيجة الإجراء في المثال<select id="wa-outcome"><option value="success" ${outcome==='success'?'selected':''}>نجاح محلي</option><option value="failure" ${outcome==='failure'?'selected':''}>فشل قابل لإعادة المحاولة</option></select></label>${btn('تحديث الصفحة','refresh')}</div>
    <section class="panel panel-pad"><p>Meta Cloud ربط رسمي. QR يستخدم Green API وقد يحتاج إعادة ربط. هذه المعاينة لا تتصل بأي مزود.</p><div class="wa-actions">${btn('ربط Meta الرسمي','meta')}${btn('طلب ربط عبر QR','request','',open||['error','loading'].includes(state)?'disabled':'')}</div>${open?'<p role="status">لديك طلب ينتظر المراجعة أو إكمال الربط.</p>':''}</section>
    ${state==='error'?`<section class="panel panel-pad" role="alert"><h2>تعذّر تحميل البيانات</h2><p>لا تعني هذه الحالة أن أرقامك غير موجودة.</p>${btn('إعادة المحاولة','refresh')}</section>`:state==='loading'?'<section role="status" class="panel panel-pad">جارٍ تحميل البيانات…</section>':`<section class="panel panel-pad"><h2>الأرقام المسجلة في الباقة</h2><p>يشمل الحد الأرقام المتوقفة. الإيقاف لا يحرر مكانًا في الباقة.</p><strong><bdi>${numbers.length} / 5</bdi></strong><p>الأماكن المتبقية: ${5-numbers.length}</p><a class="button" href="#/page/merchant/subscription">الباقة والاستخدام</a></section>
    <section class="panel panel-pad"><h2>أرقامك</h2><p>الحالة إعداد محفوظ في ساري، وليست إثباتًا لاتصال المزود الآن.</p><div class="wa-grid">${numbers.length?numbers.map(n=>`<article class="wa-number"><div class="wa-actions"><h3><bdi>${e(n.phone)||'لم يُتحقق من الرقم بعد'}</bdi></h3><span class="status gray">${labels[n.status]}</span>${n.primary?'<span class="status">الرقم الأساسي</span>':''}</div><p>Green API · QR</p><p>مسجل منذ 1 سبتمبر 2026</p><div class="wa-actions">${btn('فتح رمز الربط','qr',n.id)}${btn('تغيير الرقم','change',n.id)}${btn('التحقق وتحديث الاتصال','verify',n.id)}${n.status==='active'?`${!n.primary?btn('تعيين كأساسي','primary',n.id):''}${btn('إيقاف في ساري','pause',n.id)}`:btn('تفعيل في ساري','activate',n.id)}</div></article>`).join(''):'<p role="status">لم تسجل رقمًا بعد</p>'}</div></section>
    <section class="panel panel-pad"><h2>طلبات الربط</h2><p>اكتمال الطلب سجل لربط سابق، وليس فحصًا مباشرًا للاتصال.</p>${requests.length?requests.map(r=>`<article class="wa-number"><div class="wa-actions"><bdi>${e(r.phone)||'#'+r.id}</bdi><span class="status gray">${r.status==='pending'?'قيد المراجعة':labels[r.status]}</span>${r.source==='legacy'?'<span class="status">طلب سابق</span>':''}</div>${r.status==='rejected'?'<p>سبب الرفض: راجع الرقم قبل تقديم الطلب مجددًا.</p>':''}${r.status==='approved'?btn('فتح رمز الربط','request-qr',r.source+':'+r.id):''}</article>`).join(''):'<p role="status">لا توجد طلبات ربط</p>'}</section>`}</div>`;
  }
  function requestDialog(){openDialog('طلب ربط رقم عبر QR',`<form data-wa-form="request" class="form-stack" novalidate><p>يراجع الفريق الطلب؛ لا توجد مدة تفعيل مضمونة. محاكاة محلية فقط.</p><div class="field"><label for="wa-phone-demo">رقم واتساب مع مفتاح الدولة (اختياري)</label><input id="wa-phone-demo" name="phone" type="tel" dir="ltr" autofocus aria-describedby="wa-phone-error"><p id="wa-phone-error" role="alert"></p></div><div class="field"><label for="wa-business-demo">اسم النشاط (اختياري)</label><input id="wa-business-demo" name="business" aria-describedby="wa-business-error"><p id="wa-business-error" role="alert"></p></div><p id="wa-save-error" role="alert"></p><div class="wa-actions">${btn('إلغاء','close')}<button class="button primary" type="submit">إرسال طلب الربط</button></div></form>`);}
  function qrDialog(){openDialog('ربط واتساب',`<p>الإعدادات ← الأجهزة المرتبطة ← ربط جهاز. افتح الصفحة على شاشة أخرى لمسح الرمز.</p><div class="wa-qr-placeholder" role="img" aria-label="موضع رمز توضيحي غير صالح للربط">QR<br><small>مثال لا يربط حسابًا</small></div><p id="wa-qr-status" role="status">بانتظار المسح والتحقق…</p><div class="wa-actions">${btn('إغلاق','close')}${btn('تحديث الرمز','retry-qr')}${btn('محاكاة فشل التحقق','fail-qr')}${btn('محاكاة نجاح التحقق','scan')}</div>`);}
  document.addEventListener('change',event=>{if(event.target.id==='wa-outcome'){outcome=event.target.value;return;}if(event.target.id!=='wa-state')return;state=event.target.value;numbers=state==='empty'?[]:initial();requests=['pending','approved'].includes(state)?[{id:8,source:'legacy',status:state,phone:'966500000003'}]:state==='ready'?[{id:1,source:'legacy',status:'completed',phone:'966500000001'},{id:2,source:'current',status:'rejected',phone:'966500000003'}]:[];render();document.getElementById('wa-state')?.focus();});
  document.addEventListener('click',event=>{
    const target=event.target.closest('[data-wa-action]');if(!target)return;const action=target.dataset.waAction,id=target.dataset.waId;
    if(action==='close'){document.getElementById('dialog').close();return;}
    if(action==='refresh'){state='ready';numbers=initial();requests=[];render();return;}
    if(action==='meta'){openDialog('ربط Meta الرسمي','<p>تبدأ النسخة الفعلية إعداد Meta. هذه المعاينة لا تفتح تفويضًا ولا تحفظ رموز وصول.</p>'+btn('إغلاق','close'));return;}
    if(action==='request'){if(!requests.some(r=>['pending','approved'].includes(r.status))&&!['error','loading'].includes(state))requestDialog();return;}
    if(action==='qr'||action==='request-qr'){selected={type:action,id};qrDialog();return;}
    if(action==='retry-qr'){document.getElementById('wa-qr-status').textContent='بانتظار المسح والتحقق…';return;}
    if(action==='fail-qr'){document.getElementById('wa-qr-status').textContent='تعذّر تأكيد الاتصال. أعد التحقق؛ لم نعرض الرقم كمتصل.';return;}
    if(action==='scan'){if(selected?.type==='request-qr'){const [source,id]=selected.id.split(':');const r=requests.find(r=>r.source===source&&r.id===Number(id));if(r)r.status='completed';}else{/* Scanning verifies the session; it does not silently enable a paused number. */}document.getElementById('dialog').close();render();return;}
    if(action==='verify'){openDialog('التحقق وتحديث الاتصال',`<p>${outcome==='failure'?'تعذّر التحقق؛ لا تغيير في الرقم.':'نجح التحقق في المحاكاة فقط.'}</p>${btn('إغلاق','close')}`);return;}
    if(titles[action]){selected={type:action,id};openDialog(titles[action],`<p>${hints[action]}</p><p><bdi>${e(numbers.find(n=>n.id===Number(id))?.phone)}</bdi></p><p id="wa-action-error" role="alert"></p><div class="wa-actions">${btn('رجوع دون تغيير','close','','autofocus')}${btn('تأكيد الإجراء','confirm')}</div>`);return;}
    if(action==='confirm'&&selected){if(outcome==='failure'){document.getElementById('wa-action-error').textContent='لم يكتمل الإجراء. بقيت الحالة كما هي؛ أعد المحاولة.';return;}const n=numbers.find(n=>n.id===Number(selected.id));if(!n)return;if(selected.type==='primary'){numbers.forEach(i=>i.primary=i.id===n.id);}else{n.status=selected.type==='activate'?'active':'inactive';if(n.primary&&n.status!=='active'){n.primary=false;const next=numbers.find(i=>i.status==='active');if(next)next.primary=true;}}document.getElementById('dialog').close();if(selected.type==='change'){selected.type='qr';render();qrDialog();}else render();}
  });
  document.addEventListener('submit',event=>{if(event.target.dataset.waForm!=='request')return;event.preventDefault();const form=event.target,phone=form.elements.phone.value.replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[\s()-]/g,''),business=form.elements.business.value.trim();const invalid=phone&&!/^\+?[1-9]\d{6,14}$/.test(phone);document.getElementById('wa-phone-error').textContent=invalid?'اكتب رقمًا دوليًا صحيحًا من 7 إلى 15 رقمًا.':'';document.getElementById('wa-business-error').textContent=business.length>255?'اكتب اسمًا لا يتجاوز 255 حرفًا.':'';form.elements.phone.setAttribute('aria-invalid',String(!!invalid));form.elements.business.setAttribute('aria-invalid',String(business.length>255));if(invalid||business.length>255){(invalid?form.elements.phone:form.elements.business).focus();return;}if(outcome==='failure'){document.getElementById('wa-save-error').textContent='تعذّر تسجيل الطلب؛ بقيت بياناتك.';return;}requests.unshift({id:Date.now(),source:'current',status:'pending',phone});document.getElementById('dialog').close();render();});
  return {handles:p=>['/merchant/whatsapp','/merchant/whatsapp-instances'].includes(p.route),render:renderPage,primary:()=>{if(requests.some(r=>['pending','approved'].includes(r.status))||['error','loading'].includes(state)){openDialog('راجع حالة الربط','<p>أكمل الطلب الحالي أو أعد تحميل البيانات قبل تقديم طلب آخر.</p>'+btn('إغلاق','close'));}else requestDialog();}};
})();
